mapper.select:
SELECT COUNT(DISTINCT check_in_date)
FROM study_record
WHERE user_id = #{userId}
  AND deleted = 0
  AND check_in_date IS NOT NULL
  AND check_in_date >= #{since}

SELECT COUNT(*)
FROM word_progress
WHERE user_id = #{userId}
  AND book_id = #{bookId}
  AND deleted = 0
  AND learned = 1

SELECT COUNT(DISTINCT word_id)
FROM study_record
WHERE user_id = #{userId}
  AND deleted = 0
  AND study_date = #{date}

SELECT COUNT(*)
FROM mistake_entry
WHERE user_id = #{userId}
  AND deleted = 0
  AND create_time >= #{dayStart}
  AND create_time < #{dayEnd}
